+        int newNode() {
+            if (releasedNodes.size() > 0) {
+                return releasedNodes.pop();
+            } else {
+                return nextNode++;
+            }
+        }
+
+        void release(int node) {
+            assert node < nextNode;
+            releasedNodes.push(node);
+        }
+
+        int size() {
+            return nextNode - releasedNodes.size() - 1;
+        }
+
+    }
+
+}

