+                            mink = Math.min(mink, k.k(q, norm));
+                            maxk = Math.max(maxk, k.k(1 - q, norm));
+                            break;
+                        }
+                        singletons++;
+                    }
+                    // did we consume all the data with singletons?
+                    if (Double.isInfinite(mink) || Double.isInfinite(maxk)) {
