+            double x = digest.quantile(z);
+            assertTrue("q: " + z + " x: " + x + " last: " + lastX, Double.compare(x, lastX) >= 0);
+            lastX = x;
+
+            double q = digest.cdf(z);
+            assertTrue("Q: " + z, Double.compare(q, lastQuantile) >= 0);
+            lastQuantile = q;
+        }
+    }
